(async () => { window.__c = await (async () => { const G = window.G; const snap = () => G.cars.filter(c => c && c.position && !c.userData?.parked).map(c => [c, c.position.x, c.position.z]);
 let rechts = 0, links = 0; for (let rep = 0; rep < 16 && rechts + links < 20; rep++) { const a = snap(); await new Promise(r => setTimeout(r, 1500));
