   const t = Math.max(0, Math.min(1, ((c.position.x - ax) * ux + (c.position.z - az) * uz) / L2)); const px = ax + ux * t, pz = az + uz * t, d = Math.hypot(c.position.x - px, c.position.z - pz);
   if (d < best) { best = d; off = (c.position.x - px) * (-dz / l) + (c.position.z - pz) * (dx / l); } } }
